using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using RebirthEntityStudio;
public static class NurseHairMaterials {
 const string Folder=NurseVisualOptimization.Folder;const string Out=NurseVisualOptimization.Out;const string Native="Assets/EntityStudioGenerated/RebirthNurseNative";
 public const string Prefix="EntityStudioHair_RebirthNurse_";
 static Texture2D Read(string p){var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);t.LoadImage(File.ReadAllBytes(p));return t;}
 public static void VerifyRoleRefinement(){VerifyCandidateBindings();var rows=new List<string>();int level=0;foreach(int count in new[]{20000,9500,3000}){string root=NurseVisualOptimization.Folder+"/";var old=AssetDatabase.LoadAssetAtPath<Mesh>(root+"BeforeHairContourV1_LOD"+level+".asset");var current=AssetDatabase.LoadAssetAtPath<Mesh>(Native+"/RebirthNurse_LOD"+level+"_0.asset");var original=AssetDatabase.LoadAssetAtPath<Mesh>(root+"Blender_"+count+".asset");var before=new HashSet<string>();var triangles=old.GetTriangles(1);for(int i=0;i<triangles.Length;i+=3)before.Add(triangles[i]+","+triangles[i+1]+","+triangles[i+2]);int restored=0;var body=current.GetTriangles(0);for(int i=0;i<body.Length;i+=3)if(before.Contains(body[i]+","+body[i+1]+","+body[i+2]))restored++;var p=current.vertices;var source=original.vertices;foreach(int i in body.Distinct())if(!p[i].Equals(source[i]))throw new Exception("New body material vertex is not at original position");rows.Add("LOD"+level+" former hair triangles reassigned body="+restored+"; every current body-submesh vertex equals the original pre-contour optimized source position exactly. UVs/weights/normal/tangent fields unchanged by role partition.");level++;}File.WriteAllLines(Out+"/hair-role-refinement-audit.txt",rows);}
 public static void VerifyCandidateBindings(){string xmlPath=Out+"/nurse_entityclasses_hair_candidate.xml";var xml=System.Xml.Linq.XDocument.Load(xmlPath);var receipt=JsonUtility.FromJson<RebirthEntityBundleReceipt>(File.ReadAllText(Out+"/receipt.json"));VerifyXml(xml,receipt.bundlePath);}
 static void VerifyXml(System.Xml.Linq.XDocument xml,string bundlePath){var bundle=AssetBundle.LoadFromFile(bundlePath);if(bundle==null)throw new Exception("Candidate bundle unavailable");try{var rows=new List<string>();foreach(var entity in xml.Descendants("entity_class")){string name=(string)entity.Attribute("name");foreach(var property in entity.Elements("property")){string value=(string)property.Attribute("value");if(value==null||!value.StartsWith("#@modfolder:Resources/rebirth_rebirthnurse.unity3d?"))continue;foreach(string reference in value.Split(',')){string asset=reference.Substring(reference.IndexOf('?')+1);if(bundle.LoadAsset(asset)==null)throw new Exception("Unresolved Nurse XML asset "+name+" "+asset);rows.Add(name+" "+(string)property.Attribute("name")+"="+asset+" PASS");}}}foreach(var m in bundle.LoadAllAssets<Material>().Where(m=>m.name.StartsWith("EntityStudioHair_"))){foreach(string property in new[]{"_MainTex","_BumpMap","_SpecGlossMap","_OcclusionMap"})if(m.GetTexture(property)==null)throw new Exception("Bundled hair material property missing "+m.name+" "+property);rows.Add(m.name+" four owned texture maps present PASS");}var prefab=bundle.LoadAsset<GameObject>("RebirthNurse");foreach(var r in prefab.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.name.StartsWith("LOD")))if(r.sharedMesh.subMeshCount!=2||r.sharedMaterials.Length!=2||!r.sharedMaterials[1].name.StartsWith("EntityStudioHair_"))throw new Exception("Hair material slots do not match submeshes");File.WriteAllLines(Out+"/native-hair-xml-bindings.txt",rows.Concat(new[]{"All five class XML bundle references resolve; each LOD has body/hair slots; owned maps exist on bundled hair materials. This is asset binding verification, not gameplay."}));}finally{bundle.Unload(true);}}
 public static void Run(){
  var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/NativeReferences/Moe/Material/HD_MoeHair.mat");if(source==null)throw new Exception("Native Moe hair material unavailable");var packed=Read(Folder+"/Atlas_RMOE_Normal.png");var values=packed.GetPixels();
  foreach(bool spec in new[]{true,false}){string path=Folder+(spec?"/Atlas_HairSpecGloss.png":"/Atlas_HairOcclusion.png");var map=new Texture2D(512,512,TextureFormat.RGBA32,false,true);map.SetPixels(values.Select(c=>{float v=spec?c.r:c.b;return new Color(v,v,v,1);}).ToArray());map.Apply();File.WriteAllBytes(path,map.EncodeToPNG());AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.maxTextureSize=512;importer.sRGBTexture=false;importer.mipmapEnabled=true;var setting=importer.GetPlatformTextureSettings("Standalone");setting.overridden=true;setting.maxTextureSize=512;setting.format=TextureImporterFormat.BC7;importer.SetPlatformTextureSettings(setting);importer.SaveAndReimport();}
  var tiers=new[]{"Normal","Feral","Radiated","Charged","Infernal"};var mats=new List<Material>();foreach(string tier in tiers){string path=Native+"/"+Prefix+tier+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(source);AssetDatabase.CreateAsset(m,path);}else EditorUtility.CopySerialized(source,m);m.name=Prefix+tier;m.SetTexture("_MainTex",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_Albedo.png"));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_Normal.png"));m.SetTexture("_SpecGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_HairSpecGloss.png"));m.SetTexture("_OcclusionMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_HairOcclusion.png"));EditorUtility.SetDirty(m);mats.Add(m);}
  var raw=Read(Out+"/Atlas_Albedo.png");var reports=new List<string>();foreach(string path in new[]{Native+"/RebirthNurse_Authoring.prefab",Native+"/RebirthNurse.prefab"}){var model=PrefabUtility.LoadPrefabContents(path);foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.name.StartsWith("LOD"))){var mesh=r.sharedMesh;var vertices=mesh.vertices;var uv=mesh.uv;var all=mesh.triangles;var weights=mesh.boneWeights;var hair=new bool[vertices.Length];var forbidden=new bool[vertices.Length];
   for(int i=0;i<vertices.Length;i++){var p=r.transform.TransformPoint(vertices[i]);var c=raw.GetPixelBilinear(uv[i].x,uv[i].y);bool blue=c.b>c.r*1.13f&&c.g>c.r*1.05f;bool face=p.y>1.47f&&p.y<1.72f&&Mathf.Abs(p.x)<.085f&&p.z>.025f;bool neck=p.y>1.28f&&p.y<1.51f&&Mathf.Abs(p.x)<.065f&&p.z>.025f;forbidden[i]=blue||face||neck||p.y<1.25f;var w=weights[i];int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] ws={w.weight0,w.weight1,w.weight2,w.weight3};float influence=0,headInfluence=0,bodyInfluence=0;for(int k=0;k<4;k++){string bone=r.bones[ids[k]].name;if(bone.StartsWith("Hair_"))influence+=ws[k];else if(bone=="Head")headInfluence+=ws[k];else bodyInfluence+=ws[k];}bool blond=c.g>c.b*1.10f&&c.r<c.g*1.5f;bool spatial=p.y>1.25f&&p.y<1.74f&&Mathf.Abs(p.x)<.245f&&(p.z<-.065f||Mathf.Abs(p.x)>.085f);bool red=c.r>c.g*1.5f&&c.r>c.b*1.4f;bool hanging=influence>.02f&&(p.y>1.50f||blond)&&!red;bool headSurface=headInfluence>.5f&&spatial&&(blond||p.y>1.60f);forbidden[i]|=bodyInfluence>.20f&&influence<.20f;hair[i]=!forbidden[i]&&(hanging||(p.y>1.685f&&headInfluence>.5f)||headSurface);}
   var bodyTriangles=new List<int>();var hairTriangles=new List<int>();for(int i=0;i<all.Length;i+=3){int a=all[i],b=all[i+1],c=all[i+2];int votes=(hair[a]?1:0)+(hair[b]?1:0)+(hair[c]?1:0);var list=votes>=2&&!forbidden[a]&&!forbidden[b]&&!forbidden[c]?hairTriangles:bodyTriangles;list.Add(a);list.Add(b);list.Add(c);}if(hairTriangles.Count<90||bodyTriangles.Count<300)throw new Exception("Hair material mask empty or consumes body");mesh.subMeshCount=2;mesh.SetTriangles(bodyTriangles,0);mesh.SetTriangles(hairTriangles,1);if(!vertices.SequenceEqual(mesh.vertices)||!uv.SequenceEqual(mesh.uv)||all.Length!=mesh.triangles.Length)throw new Exception("Material split changed surface data");var prior=Enumerable.Range(0,all.Length/3).Select(i=>all[i*3]+","+all[i*3+1]+","+all[i*3+2]).OrderBy(x=>x).ToArray();var after=mesh.triangles;var actual=Enumerable.Range(0,after.Length/3).Select(i=>after[i*3]+","+after[i*3+1]+","+after[i*3+2]).OrderBy(x=>x).ToArray();if(!prior.SequenceEqual(actual))throw new Exception("Material split lost/duplicated/reversed triangles");EditorUtility.SetDirty(mesh);r.sharedMaterials=new[]{r.sharedMaterials[0],mats[0]};reports.Add(path+" "+r.name+" body="+bodyTriangles.Count/3+" hair="+hairTriangles.Count/3+"; all original vertices/UVs/triangles retained; face/neck/blue/red and torso-weighted cloth exclusions applied; spatial mask requires Head influence rather than assigning all shoulder surfaces to hair.");}
   var workspace=model.GetComponent<RebirthEntityRigWorkspace>();if(workspace!=null)foreach(var row in workspace.rendererTierMaterials.Where(row=>row.renderer!=null&&row.renderer.name.StartsWith("LOD"))){var bodies=Enumerable.Range(0,5).Select(t=>row.variants[t*row.slotCount]).ToArray();row.slotCount=2;row.sourceMaterials=new List<Material>{bodies[0],mats[0]};row.variants=Enumerable.Range(0,5).SelectMany(t=>new[]{bodies[t],mats[t]}).ToList();}
   PrefabUtility.SaveAsPrefabAsset(model,path);PrefabUtility.UnloadPrefabContents(model);
  }
  string manifestPath=RebirthEntityPrefabExporter.ManifestPath(Native+"/RebirthNurse.prefab");var manifest=JsonUtility.FromJson<RebirthEntityPrefabManifest>(File.ReadAllText(manifestPath));manifest.tierMaterialAssetPaths=manifest.tierMaterialAssetPaths.Where(p=>!Path.GetFileName(p).StartsWith(Prefix)).Concat(mats.Select(AssetDatabase.GetAssetPath)).ToArray();File.WriteAllText(manifestPath,JsonUtility.ToJson(manifest,true));AssetDatabase.SaveAssets();File.WriteAllLines(Out+"/native-hair-material-fit.txt",reports.Concat(new[]{"HD_MoeHair native Game/Autodesk material copied, including cutout/native keywords; owned 2K albedo/normal and 512 specular-gloss/occlusion maps. Alpha currently opaque; no silhouette change or cloth reconstruction claimed. Rig/collider transforms unchanged. Runtime binder must preserve the EntityStudioHair_ role."}));
 }
}

